from docx import Document
from docx.shared import Inches, Pt, RGBColor
D=Document(); s=D.sections[0]
s.top_margin=s.bottom_margin=Inches(.65); s.left_margin=s.right_margin=Inches(.75)
for name in ['Normal','Title','Heading 1','Heading 2']:
 st=D.styles[name]; st.font.name='Calibri'; st.font.color.rgb=RGBColor(0,0,0)
D.styles['Normal'].font.size=Pt(11); D.styles['Normal'].paragraph_format.space_after=Pt(6)
D.styles['Title'].font.size=Pt(23); D.styles['Heading 1'].font.size=Pt(15)
def p(t): D.add_paragraph(t)
def h(t,steps):
 D.add_heading(t,1); q=D.add_paragraph(steps); q.runs[0].italic=True

def c(t):
 q=D.add_paragraph(); q.paragraph_format.space_after=Pt(8)
 r=q.add_run(t); r.font.name='Consolas'; r.font.size=Pt(10)
def b(t): D.add_paragraph(t,style='List Bullet')
D.add_heading('Food Delivery API Group Procedures',0)
p('Use GitHub to share the project, Docker to build and run the services, AWS to deploy them, and Postman to test the APIs. Each group works on its own computer. The procedure follows the group assignments for the Restaurant and Menu services.')
D.add_heading('Shared GitHub Workflow',1)
p('For the first setup, open the shared GitHub repository, choose Code, and copy its HTTPS URL. Use GitHub Desktop to clone it to your own computer, then open the cloned project folder in your terminal. For an existing local clone, retrieve the latest changes before starting:')
c('git pull')
p('GitHub shares the source code, Dockerfiles, and Docker Compose configuration. Each computer builds its own Docker images. Amazon ECR stores the uploaded images. Keep AWS credentials out of GitHub.')
h('Group 1 Services and Docker Images','Steps 1 to 5')
p('Verify the Node.js and Docker environment. Start Docker and run these commands from the main project folder:')
c('node --version\nnpm --version\ndocker --version')
p('Prepare the Restaurant Service on port 3001 and Menu Service on port 3002, with a Dockerfile for each service. Build the images:')
c('docker build -t restaurant-service ./restaurant-service\ndocker build -t menu-service ./menu-service')
p('Commit and push the service code, Dockerfiles, and docker-compose.yml to GitHub using GitHub Desktop. Other groups can then pull the files on their own computers.')
p('To run both services locally:')
c('docker compose up --build -d')
p('In Postman, select GET and test http://localhost:3001/restaurants, http://localhost:3002/menu, and http://localhost:3001/restaurants/1/menu. Select Send for each request.')
D.add_page_break()
h('Group 2 ECR Repositories','Step 6')
p('In the AWS Console, open Elastic Container Registry, select Private repositories, and choose Create repository. Create restaurant-service and menu-service in the same project region. If they already exist, use the existing repositories. Share the repository details with Groups 3, 4, and 6.')
h('Group 3 AWS CLI and Docker Authentication','Steps 7 and 8')
p('Configure AWS CLI on your own computer with authorized AWS credentials and the region containing the ECR repositories:')
c('aws --version\naws configure\naws sts get-caller-identity')
p('In AWS ECR, open restaurant-service and select View push commands. Run the displayed login command in your terminal. It includes the actual account ID and region. Use the commands appropriate for your terminal.')
p('Each group that runs AWS CLI or uploads images must configure its own computer and authenticate there. The login performed on another group\'s computer does not authenticate yours.')
h('Group 4 Tag and Push Images','Steps 9 and 10')
p('Clone the shared GitHub repository on your own computer if needed. In the local project folder, pull the latest changes, start Docker, and build both images:')
c('git pull\ndocker build -t restaurant-service ./restaurant-service\ndocker build -t menu-service ./menu-service')
p('Complete the Group 3 AWS CLI configuration and ECR login on this computer. In ECR, open restaurant-service, select View push commands, and run the displayed tag and push commands for restaurant-service:latest. Repeat for menu-service:latest in the menu-service repository.')
p('Confirm that each ECR repository contains an image tagged latest. Use the repository-specific commands from AWS so the account ID, region, and repository address are correct.')
h('Group 5 ECS Cluster','Step 11')
p('In the AWS Console, open Elastic Container Service, select Clusters, and choose Create cluster. Create the cluster for the Restaurant and Menu services using AWS Fargate. Share the cluster name and region with Groups 6 and 7.')
D.add_page_break()
h('Group 6 Task Definitions and Fargate','Steps 12 to 14')
p('In ECS, open Task definitions and choose Create new task definition. Create separate definitions with Fargate compatibility:')
b('Restaurant Service: Restaurant ECR image, container port 3001.')
b('Menu Service: Menu ECR image, container port 3002.')
p('Configure CPU, memory, and a task execution role with permission to pull images from ECR. For the Restaurant container, configure MENU_SERVICE_URL with a Menu address reachable from the Restaurant task. If AWS Cloud Map is configured, use the actual Menu DNS name. If using a public task IP, update the setting whenever that IP changes.')
h('Group 7 Networking and Deployment','Steps 15 and 16')
p('In the ECS cluster, create a service for each task definition. Configure the VPC, subnets, security groups, and Fargate networking. For direct public access, enable public IP assignment and use subnets with internet connectivity.')
p('Configure these inbound security group rules and select Save rules:')
b('Restaurant: Custom TCP, port 3001, source Anywhere-IPv4 (0.0.0.0/0).')
b('Menu: Custom TCP, port 3002, source Anywhere-IPv4 (0.0.0.0/0).')
p('Keep the existing Menu rule whose source is a security group ID beginning with sg-. Replacing the individual IP address ending in /32 with Anywhere-IPv4 allows classmates and other internet users to access the specified ports. Share the current task public IPs for Postman testing.')
h('Group 1 Final Postman Testing','Step 18')
p('Create a Postman collection named Food Delivery API. Add these GET requests and select Send for each:')
for label,url in [('Restaurant status','http://3.26.198.35:3001/'),('Restaurant list','http://3.26.198.35:3001/restaurants'),('Menu status','http://16.176.192.32:3002/'),('Menu list','http://16.176.192.32:3002/menu'),('Restaurant and Menu integration','http://3.26.198.35:3001/restaurants/1/menu')]:
 q=D.add_paragraph(); q.paragraph_format.space_after=Pt(3); q.add_run(label+'  ').bold=True; r=q.add_run(url); r.font.size=Pt(10)
p('Expected result: 200 OK with JSON data. If the integration request returns 503, check MENU_SERVICE_URL and connectivity to the Menu Service. Update Postman URLs if the ECS task public IPs change. Save the collection and screenshots of successful responses for documentation.')
D.core_properties.title='Food Delivery API Group Procedures'
D.save('outputs/Food_Delivery_Group_Procedures.docx')
print('Rebuilt full document with GitHub workflow for all groups.')
